 const search=(S.ownerMenuSearch||'').toLowerCase().trim();const category=S.ownerMenuCategory||'all';
 const visible=items.filter(it=>(category==='all'||String(it.category_id)===category)&&(!search||it.name.toLowerCase().includes(search)));
 const html=card('Menu management',`<div class="row between wrap"><p class="muted small">${items.length} dishes · ${items.filter(it=>Number(it.available)===1).length} available</p><div class="row"><button class="btn ghost mini" id="add-cat">＋ Category</button><button class="btn mini" id="add-item">＋ Add new dish</button></div></div><p class="caption mt10">Edit prices, portions and photos anytime. Mark a dish sold out to stop orders; make it available when it is back.</p><div class="grid2 mt20"><input id="owner-menu-search" class="input" aria-label="Search your dishes" placeholder="Search your dishes..." value="${esc(S.ownerMenuSearch||'')}"><select id="owner-menu-category" aria-label="Filter menu category">${opts([['all','All categories'],...categories.map(c=>[c.id,c.name])],category)}</select></div><div class="line"></div>${visible.length?visible.map(it=>`<div class="admin-menu-row">${image(it)}<div class="grow"><h4>${esc(it.name)}</h4><p>${esc(categories.find(c=>String(c.id)===String(it.category_id))?.name||'Uncategorized')} · ${it.options.length?`From ${money(Math.min(...it.options.map(o=>+o.price)))}`:money(it.base_price)} · ${Number(it.available)===1?'Available':'Sold out'}</p></div><div class="row wrap"><button class="btn mini ghost" data-toggle="${it.id}" aria-label="${Number(it.available)===1?'Mark sold out':'Make available'}: ${esc(it.name)}">${Number(it.available)===1?'Mark sold out':'Make available'}</button><button class="btn mini outline" data-edit="${it.id}">Edit</button><button class="btn mini danger" data-delete="${it.id}" aria-label="Remove ${esc(it.name)}">×</button></div></div>`).join(''):`<div class="empty">${items.length?'No dishes match your filters.':'Your menu is empty. Add your first dish!'}</div>`}`);
 adminLayout('owner','Menu studio','Control your dishes, prices, portions and availability.',html);
