 $('#owner-menu-category').onchange=e=>{S.ownerMenuCategory=e.target.value;renderOwnerMenu()};
 $('#add-item').onclick=()=>menuEditor(null);$('#add-cat').onclick=()=>categoryManager(categories,items); $$('[data-edit]').forEach(b=>b.onclick=()=>menuEditor(items.find(i=>String(i.id)===b.dataset.edit)));
