 $('#size-template').onchange=e=>{d.options=[];renderVariant()};$('#add-extra').onclick=()=>{syncAddons();d.addons.push({name:'',price:0});renderAddons()};$('#photo-remove').onclick=()=>{d.image_url='';d.image_credit='';d.image_license='';d.image_source_url='';$('#photo-url').value='';$('#photo-preview').innerHTML='<p class="caption">Photo skipped</p>'};
 function selectPhoto(url){d.image_url=url;d.image_credit='';d.image_license='';d.image_source_url='';$('#photo-url').value=remoteImageUrl(url)?url:'';$('#photo-preview').innerHTML=image(d)}
 function useImageLink(){const url=$('#photo-url').value.trim();if(!remoteImageUrl(url))throw Error('Paste a valid HTTPS image link, up to 800 characters');selectPhoto(url);toast('Image link selected. Check the preview before saving.')}
